-- ScholarBridgeAi — Scholarship rewrite pass 32 (Australia)
-- Verified 2026-10-25 against the providers' own pages. Australian universities price almost every
-- one of these awards as a PERCENTAGE of tuition, not as a dollar sum, so amount_usd_value = 0 and
-- award_amount = NULL throughout: the money is real, the number simply does not exist in the
-- provider's own text. award_currency is AUD wherever a dollar figure IS published.

-- 533 Adelaide University — the University of Adelaide no longer exists; the award is now the
-- Adelaide Academic Excellence Scholarship (50%) inside the merged Adelaide University ladder
UPDATE scholarships SET
  title = 'Adelaide Academic Excellence Scholarship (50%)',
  provider = 'Adelaide University',
  description = 'The institution this record used to describe no longer exists: the University of Adelaide merged with the University of South Australia and now trades as Adelaide University, and the scholarship ladder was rebuilt with the merge. The top rung is the Adelaide Academic Excellence Scholarship, a 50% tuition fee reduction for the standard full-time duration of an undergraduate or postgraduate coursework degree, and it is deliberately hard - limited places, a selection panel and a rolling review until the places run out. Below it sit three automatic awards that need no application: the Adelaide Emerging Leaders Award at 25% for a distinction average, the Adelaide Merit Scholarship at 15% for a credit average, and three 10% awards for siblings of students or alumni, alumni of Adelaide, UniSA or the old University of Adelaide, and students from partner institutions. The 50% award requires either an ATAR of 99 or an international equivalent for a school-leaver, or an overall GPA of 6.7 on a 7.0 scale for undergraduate and postgraduate applicants alike, and it excludes the clinical degrees - dentistry, medicine, medical radiation, midwifery, occupational therapy, physiotherapy, podiatry, veterinary science, speech pathology - plus the MBA. Recipients must keep a program term GPA of 5.5 or the discount pauses until the average recovers. Applications opened on Monday 24 August 2026 and close when the allocation is exhausted.',
  requirements = 'Be an international student applying to a CRICOS-registered bachelor degree of at least 96 units or 2 years after credit, or a CRICOS-registered master degree of at least 72 units or 1.5 years after credit, at Adelaide University. Meet one of: an ATAR of 99 or international equivalent for an undergraduate applicant, or an overall GPA of 6.7 on a 7.0 scale for an undergraduate or postgraduate applicant. Not be applying to an excluded clinical program or the MBA, not be an Australia Awards recipient, and not hold a sponsor tuition fee waiver equal to or greater than the scholarship value. Submit the scholarship application form; the 25%, 15% and 10% awards need no form and are assessed automatically. Maintain a program term GPA of 5.5 on a 7.0 scale to keep receiving the discount.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = 'A 50% tuition fee reduction for the standard duration of the degree. The automatic alternatives are 25% for a distinction average, 15% for a credit average, and 10% for siblings, alumni and partner-institution applicants.',
  english_requirements = 'The scholarship sets no separate English score; the Adelaide University admission English requirement for the chosen degree applies.',
  required_documents = '["Adelaide Academic Excellence Scholarship application form","Academic transcripts showing the GPA or ATAR used for admission","Offer of admission for an eligible CRICOS-registered degree","English proficiency evidence as the degree requires","Proof of visa status or a statement that a student visa will be sought"]',
  deadline = 'Applications opened on 24 August 2026 and are assessed on a rolling basis until all places are exhausted; no closing date is published',
  deadline_date = NULL, deadline_type = 'rolling', application_status = 'open',
  website_url = 'https://adelaide.edu.au/study/scholarships/int/adelaide-academic-excellence-scholarship-50/',
  source_url = 'https://adelaide.edu.au/study/scholarships/international-students-scholarships/',
  application_url = 'https://adelaide.edu.au/study/scholarships/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from Adelaide University own pages fetched 2026-10-25: adelaide.edu.au/study/scholarships/international-students-scholarships lists the six international awards - Academic Excellence 50%, Emerging Leaders 25%, Merit 15%, Sibling 10%, Global Alumni 10% and Partner Award 10% - and states that for most scholarships students are automatically assessed when applying, though some need an application; adelaide.edu.au/study/scholarships/int/adelaide-academic-excellence-scholarship-50 gives the eligibility rules (ATAR 99 or GPA 6.7, CRICOS unit thresholds, the excluded program list, the Australia Awards and sponsor-waiver exclusions), the panel-based rolling selection, the applications opening date of Monday 24 August 2026, and the minimum program term GPA of 5.5 that governs continuation. CORRECTIONS: this is a structural correction, not a numerical one. The row named a scholarship - Adelaide Global Academic Excellence Scholarship - and a provider - The University of Adelaide - that no longer exist after the merger into Adelaide University, carried an invented USD 30 000, claimed a blanket Full Tuition, listed all three degree levels and gave a typical October-November deadline. The real top award is 50% of tuition, the ladder below it is automatic, the provider is Adelaide University, and the only date Adelaide publishes is the opening date with a rolling close. amount_usd_value is 0 because Adelaide prices the award as a percentage, not as a sum.'
WHERE id = 533;

-- 561 Curtin University
UPDATE scholarships SET
  title = 'John Curtin Global Excellence Scholarship',
  description = 'Curtin does not run one scholarship called Curtin International Scholarships; it runs a ladder, and the top of the ladder is the John Curtin Global Excellence Scholarship at 40% off the tuition fee for the duration of the course. The rung below is the Curtin Global Merit Scholarship at 20% off tuition for the duration, again merit-based. Alongside the two percentage awards sit three fixed credits: the Global Future Leaders Scholarship at a one-off A$10 000 towards tuition, the Curtin Global Talent Scholarship at a one-off A$10 000 for students who began at a Curtin global campus or a recognised offshore joint programme, and the Global Scholars Program Scholarship at a one-off A$15 000 for students who study at two Curtin campuses. A Curtin English pathway also returns up to A$7 496 in credit. The practical point for an applicant from Uzbekistan is that none of these is a cash payment and none is automatically the full 40% - the level is assessed from the academic record attached to the admission application, and Curtin publishes no single closing date for the international ladder at all, so the admission round is the deadline.',
  requirements = 'Be an international student applying for an eligible Curtin coursework degree at an Australian campus (the Global Scholars Program additionally requires study at two Curtin campuses). Present academic results strong enough for the level applied for; Curtin assesses the percentage level from the qualification used for admission and publishes the detailed criteria on its scholarship database rather than on the summary page. Hold an offer and accept it, since the credit or percentage is applied against the offer. Not hold a conflicting award for the same tuition.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction and one-off tuition credits',
  tuition_coverage = '40% off tuition for the duration for the John Curtin Global Excellence Scholarship, 20% for the Curtin Global Merit Scholarship, plus one-off credits of A$10 000 (Global Future Leaders and Global Talent) and A$15 000 (Global Scholars Program). No award covers living costs.',
  english_requirements = 'The award sets no separate English score; the Curtin admission English requirement applies. The Curtin English Scholarship separately returns up to A$7 496 in credit when a Curtin English course is completed as a pathway.',
  required_documents = '["Curtin admission application","Academic transcripts used for the scholarship assessment","English proficiency evidence","Offer acceptance and deposit","Passport copy"]',
  deadline = 'No standalone closing date is published for the international ladder; assessment follows the admission round of the intake applied for',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'open',
  expected_deadline_period = 'Aligned with Curtin admission rounds for each intake; Curtin publishes opening and closing dates per award in its scholarship database rather than on the summary page.',
  website_url = 'https://www.curtin.edu.au/study/scholarships/international-scholarships/',
  source_url = 'https://www.curtin.edu.au/study/scholarships/international-scholarships/',
  application_url = 'https://www.curtin.edu.au/study/scholarships/find-a-scholarship/#!/?page=1&perPage=10&filters=Citizenship:INTERNATIONAL',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Curtin University international scholarships page fetched 2026-10-25 (curtin.edu.au/study/scholarships/international-scholarships), which lists the John Curtin Global Excellence Scholarship at 40% off tuition for the duration, the Curtin Global Merit Scholarship at 20% off tuition for the duration, the Global Future Leaders Scholarship at a one-off A$10 000, the Curtin Global Talent Scholarship at a one-off A$10 000, the Global Scholars Program Scholarship at a one-off A$15 000, and the Curtin English Scholarship at up to A$7 496. CORRECTIONS: the row was titled Curtin International Scholarships, which is not the name of any award, claimed a Partial Tuition award worth USD 27 000, listed all three degree levels and gave a varies-November-December deadline. The real ceiling is 40% of tuition for the duration, there is no dollar headline at all, the award is coursework only, and Curtin publishes no standalone closing date. amount_usd_value is 0 because the provider prices the award as a percentage.'
WHERE id = 561;

-- 564 Deakin University
UPDATE scholarships SET
  title = 'Deakin International Scholarship for Excellence (25%)',
  description = 'Deakin grades its international awards by academic result and most of them need no application: when you apply for a Deakin degree you are assessed automatically, and the outcome arrives by email usually within four weeks of the closing date. The 25% rung is the Deakin International Scholarship for Excellence, a 25% tuition fee reduction for the duration of the undergraduate or postgraduate degree. Below it the Deakin International 20% Merit Scholarship offers 20% on the same automatic basis. Above both sits the Deakin Vice-Chancellor International Scholarship, which is the only one in the ladder that needs a separate application and which pays either 100% or 50% of tuition for the duration - a genuinely different award, not a bigger version of the same form. Two smaller items round out the list and neither helps an applicant from Uzbekistan: the Deakin Southeast Asia Priority Bursary pays a one-off amount of up to AUD 2 000 and is restricted to Southeast Asian applicants, and the Deakin alumni discount gives 10% per unit to returning Deakin graduates. Deakin College pathway students have their own scholarship, so a student entering through the college should read that page rather than this one.',
  requirements = 'Be an international applicant for an eligible Deakin undergraduate or postgraduate coursework degree and hold an offer. Most awards, including the 25% and 20% levels, are assessed automatically from the academic record submitted with the admission application and need no separate form. The Vice-Chancellor International Scholarship at 100% or 50% requires a separate application and is assessed against a different, higher academic standard. Meet the Deakin academic and English entry requirements for the chosen degree. Students entering through Deakin College should use the pathway scholarship instead.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = '25% of tuition for the duration of the degree for the Scholarship for Excellence, 20% for the Merit Scholarship, and 100% or 50% for the separately applied Vice-Chancellor International Scholarship. No living allowance in any of them.',
  english_requirements = 'The awards set no separate English score; the Deakin admission English requirement for the chosen degree applies.',
  required_documents = '["Deakin admission application","Academic transcripts","English proficiency evidence","Offer acceptance","Separate application form only for the Vice-Chancellor International Scholarship"]',
  deadline = 'No separate closing date for the automatic 25% and 20% awards; they are assessed with the admission application and outcomes follow within about four weeks of the closing date',
  deadline_date = NULL, deadline_type = 'not_published', application_status = 'open',
  expected_deadline_period = 'Tied to Deakin trimester intakes; the separate Vice-Chancellor International Scholarship runs its own round with a published close date.',
  website_url = 'https://www.deakin.edu.au/international-students/international-student-scholarships',
  source_url = 'https://www.deakin.edu.au/international-students/international-student-scholarships',
  application_url = 'https://www.deakin.edu.au/study/fees-and-scholarships/scholarships/find-a-scholarship',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Deakin University international student scholarships page fetched 2026-10-25, which states that applicants are automatically considered for most international scholarships on academic merit when they apply, that the Vice-Chancellor International Scholarship offers a 100% or 50% tuition fee reduction for the duration and requires a separate application, that the Deakin International Scholarship for Excellence offers a 25% reduction for the duration, that the Deakin International 20% Merit Scholarship offers 20%, and that successful applicants are emailed usually within four weeks of the closing date; the same page lists the Deakin Southeast Asia Priority Bursary at a one-off amount of up to AUD 2 000 and the alumni discount at 10% per unit. CORRECTIONS: the row was titled Deakin International Scholarship, claimed a Partial Tuition award worth USD 27 000, listed all three degree levels and gave a variable October-November deadline. The real rungs are 25% and 20% of tuition, with a separately applied 100% or 50% award above them, and no dollar headline exists. amount_usd_value is 0 because the provider prices the awards as percentages.'
WHERE id = 564;

-- 584 Griffith University
UPDATE scholarships SET
  title = 'Griffith Vice Chancellor International Scholarship',
  description = 'Griffith pays half the tuition and the way to win it changed in a way the old record never mentioned. The Vice Chancellor International Scholarship covers 50% of undergraduate or postgraduate coursework tuition for the whole degree and is open to students starting in 2026 or 2027, but it requires a minimum GPA of 6.0 on a 7.0 scale in previous studies, a full offer, and then a separate scholarship application with academic records and a personal statement that a university panel reviews. The closing dates are tied to the trimester: 15 August 2026 for a Trimester 3 2026 start, 28 November 2026 for Trimester 1 2027, with 2 January 2027 reserved for applicants completing Australian Year 12 in that cycle, and 10 April 2027 for Trimester 2 2027. Numbers are limited and the office closes the round when acceptances reach the cap. Recipients must keep a cumulative GPA of 5.5 annually to keep each year deduction, must remain an international fee-paying student, and are expected to be profiled in Griffith marketing. Excluded are higher degree research, online, non-award, Study Abroad, diploma, Masters Qualifying Program, the MBA under program code 5158, ELICOS, part-time-only degrees and offshore partner delivery. Griffith also still lists the Griffith Remarkable Scholarship at the same 50% but with a 5.5 entry GPA; its published cycle has not been refreshed past 2023, so the verified live route is the Vice Chancellor award.',
  requirements = 'Be a citizen of a country other than Australia or New Zealand. Be a new, commencing student holding an offer to study by the scholarship closing date for your trimester. Have a minimum GPA of 6.0 on a 7.0 scale or equivalent in previous studies for the Vice Chancellor International Scholarship. Satisfy all academic and English entry requirements for the chosen undergraduate or postgraduate coursework program. Apply for the scholarship separately after receiving the letter of offer, submitting academic records and a personal statement. Be enrolled full time and maintain a cumulative GPA of 5.5 on a 7.0 scale annually to keep each year deduction. Not be enrolled in higher degree research, online, non-award, Study Abroad, diploma, Masters Qualifying Program, MBA 5158, ELICOS, part-time-only or offshore partner programs.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = '50% of undergraduate or postgraduate coursework tuition for the duration of the program, subject to a cumulative GPA of 5.5 each year. Tuition only: no living allowance, no airfare, no health cover.',
  english_requirements = 'The scholarship sets no separate English score; the Griffith academic and English entry requirements for the chosen degree apply.',
  required_documents = '["Griffith admission application and letter of offer","Academic transcripts","Personal statement","English proficiency evidence","Scholarship application form submitted by the trimester closing date"]',
  deadline = '28 November 2026 for a Trimester 1 2027 start; 2 January 2027 for applicants completing Australian Year 12; 10 April 2027 for Trimester 2 2027; 15 August 2026 for Trimester 3 2026',
  deadline_date = '2026-11-28', deadline_type = 'fixed', application_status = 'open',
  website_url = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship',
  source_url = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship',
  application_url = 'https://www.griffith.edu.au/international/scholarships-finance/scholarships/application',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from the Griffith University Vice Chancellor International Scholarship page fetched 2026-10-25, which gives the 50% of tuition value for the whole degree, the 2026 or 2027 start window, the minimum entry GPA of 6.0 on a 7.0 scale, the requirement to apply separately after the letter of offer with academic records and a personal statement, the closing dates of 15 August 2026, 28 November 2026, 2 January 2027 and 10 April 2027, the annual continuation GPA of 5.5, the requirement to remain international fee-paying, the marketing-profile expectation, and the full exclusion list. The Griffith Remarkable Scholarship page was also opened the same day; it returns a 2023 terms-and-conditions document marked closed to new applicants and a body text that still reads Trimester 1, 2 or 3 2023, so it was not treated as a verified 2027 route. CORRECTIONS: the row was titled Griffith Remarkable Scholarship, claimed a Partial Tuition award worth USD 26 000, listed all three degree levels and gave a September-November deadline. The live award is the Vice Chancellor International Scholarship at 50% of tuition, the entry threshold is 6.0 rather than the Remarkable 5.5, the closing dates are trimester-specific and one of them is 28 November 2026, and no dollar figure exists. amount_usd_value is 0 because Griffith prices the award as a percentage.'
