-- 664 RMIT University — the one Australian award in this pass written specifically for Uzbekistan
UPDATE scholarships SET
  title = 'RMIT Academic Merit Scholarship for Central Asia and Mongolia',
  description = 'This is the Australian scholarship in the catalogue that names Uzbekistan in its own eligibility text, which is why it replaces the generic international award the record used to carry. RMIT provides a 20% tuition fee reduction for the duration of eligible qualifications to outstanding students from Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan, Uzbekistan or Mongolia, and it requires the applicant to be applying from offshore in one of those countries. The academic threshold is an Australian-equivalent GPA of 2.5, a 70% average, or an ATAR of 75 in the qualification used for admission, and the applicant must hold a full or conditional offer to commence in Semester 1 2027 in a vocational course, an associate degree, a bachelor degree, a graduate certificate, a graduate diploma or a masters by coursework. Two aviation programs are excluded: the Associate Degree in Aviation (Professional Pilots) and the Bachelor of Aviation (Pilot Training). The mechanics are first-come, first-served and unusually strict: an Expression of Interest form is required, the scholarship became available on 21 October 2026, it cannot be deferred to another intake, and once the offer letter is issued the student must accept the offer and pay the deposit within 14 days to secure the discount. It is revoked if the student visa lapses or if any other RMIT, Australian or foreign-government scholarship covering tuition is granted.',
  requirements = 'Be a citizen of Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan, Uzbekistan or Mongolia and be applying offshore from one of those countries. Hold a valid student visa or plan to apply for one before the course begins. Achieve an Australian-equivalent GPA of 2.5, a 70% average, or an ATAR of 75 in the qualification used for admission. Hold a full or conditional offer to commence in Semester 1 2027 in a vocational course, associate degree, bachelor degree, graduate certificate, graduate diploma or masters by coursework, excluding the Associate Degree in Aviation (Professional Pilots) and the Bachelor of Aviation (Pilot Training). Not be an existing RMIT student, although students completing RMIT ELICOS or Foundation Studies may qualify once those finish. Submit the Expression of Interest form, since the discount is not automatic, and accept the offer with the deposit within 14 days of the offer letter because places are first-come, first-served.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]',
  eligible_countries = '["Kazakhstan","Kyrgyzstan","Tajikistan","Turkmenistan","Uzbekistan","Mongolia"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = 'A 20% tuition fee reduction for the duration of the eligible course, applied to tuition only and non-refundable. It does not cover living costs, Overseas Student Health Cover, flights or accommodation.',
  english_requirements = 'The scholarship sets no separate English score; the RMIT admission English requirement for the chosen program applies.',
  required_documents = '["Expression of Interest form for the scholarship","RMIT application and offer letter for Semester 1 2027","Academic transcripts showing the GPA or 70% average","English proficiency evidence","Passport copy and proof of offshore application","Offer acceptance and deposit within 14 days"]',
  deadline = 'Offers must be for a Semester 1 2027 commencement; the scholarship is open until all places are filled and is first-come, first-served, with the discount secured by accepting the offer and paying the deposit within 14 days',
  deadline_date = NULL, deadline_type = 'rolling', application_status = 'open',
  expected_deadline_period = 'Open from 21 October 2026 until places are exhausted, for Semester 1 2027 commencement.',
  website_url = 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-central-asia-mongolia',
  source_url = 'https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-central-asia-mongolia',
  application_url = 'https://www.rmit.edu.au/scholarships/international-scholarships',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from two RMIT University pages fetched 2026-10-25: rmit.edu.au/scholarships/international-scholarships lists the award as Academic Merit Scholarship for Central Asia and Mongolia, described as a 20% tuition fee reduction for the duration of eligible qualifications for students from Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan, Uzbekistan or Mongolia; rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-central-asia-mongolia gives applications open, open until all places are filled, the 20% value, the citizenship and offshore-application conditions, the Australian-equivalent GPA 2.5 or 70% average or ATAR 75 threshold, the Semester 1 2027 offer requirement across vocational, associate degree, bachelor, graduate certificate, graduate diploma and masters by coursework, the two aviation exclusions, the 21 October 2026 effective date, the first-come first-served rule with the 14-day acceptance and deposit window, the no-deferral rule, and the revocation conditions for visa lapse and for other RMIT, Australian or foreign-government scholarships. CORRECTIONS: the row was titled RMIT International Excellence Scholarship, claimed a Partial Tuition award worth USD 26 000, listed all three degree levels and gave a September-December deadline. RMIT does not run an award by that name for commencing international students in Melbourne, and the real award that a student from Uzbekistan can win is the Central Asia and Mongolia one at 20% of tuition. eligible_countries was narrowed from All to the six countries RMIT actually names. amount_usd_value is 0 because RMIT prices the award as a percentage.'
