-- 751 University of Newcastle
UPDATE scholarships SET
  title = 'University of Newcastle International Excellence Scholarship',
  description = 'Newcastle expresses this award as a percentage rather than a sum: the International Excellence Scholarship is worth 20% of the gross annual international tuition fee, applied as a tuition fee reduction against each term of the eligible program, and it is pro-rated where a student carries a reduced load, holds credit or completes only part of a year. There is no application at all - the scholarship is assessed automatically when the admission application is lodged and the value appears in the letter of offer - and 500 places are available for students commencing in 2027 or later. It is open to undergraduate and postgraduate coursework students and excludes higher degree research, the English Language Bridging Program, exchange and Study Abroad, standalone graduate certificates and diplomas, and programs delivered online or offshore. The 2025 terms and conditions document quantified the same award at AUD 6 000 a year and AUD 750 per 10-unit course, which is a useful scale check against an annual international fee north of AUD 30 000, but the current version of the scholarship is defined as 20% rather than as a fixed sum. Two related awards exist and neither is general: the Excelencia Internacional Scholarship at 25% plus up to 12 weeks of fully funded on-campus accommodation and up to 60 hours of free English tuition is restricted to students from South and Central America, and the AUD 1 500 Global Access Grant is only for recipients of the university own international scholarships.',
  requirements = 'Be an international full fee-paying student commencing an eligible CRICOS-registered undergraduate or postgraduate coursework degree at the University of Newcastle in 2027 or later. Not be enrolled in a program covered by an international quota arrangement. Not be the beneficiary of a separate University of Newcastle scholarship unless special dispensation has been granted. Be able to meet the financial obligations the Australian Government sets for a full fee-paying international student, with evidence provided if requested. No separate scholarship application is required: the award is assessed automatically on application for admission and the value is stated in the letter of offer. Higher degree research, English Language Bridging, exchange and Study Abroad, standalone graduate certificate and diploma, and online or offshore programs are excluded.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s","Master''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = 'A dollar value equivalent to 20% of the gross annual international tuition fee for each year of study at a standard full-time load of 80 units, applied term by term and pro-rated for reduced loads or credit. 500 places for 2027 commencements. No living allowance.',
  english_requirements = 'The scholarship sets no separate English score; the University of Newcastle admission English requirement applies. Applicants who need additional English tuition may receive up to 60 hours at no cost only under the separate Excelencia Internacional Scholarship, which is restricted to the Americas.',
  required_documents = '["University of Newcastle admission application","Academic transcripts","English proficiency evidence","Evidence of ability to meet Australian financial requirements if requested","No separate scholarship application"]',
  deadline = 'No separate scholarship deadline; automatically assessed with the admission application and confirmed in the letter of offer for 2027 commencements',
  deadline_date = NULL, deadline_type = 'automatic', application_status = 'open',
  website_url = 'https://www.newcastle.edu.au/scholarships/UNI_053',
  source_url = 'https://www.newcastle.edu.au/scholarships/international-scholarships',
  application_url = 'https://www.newcastle.edu.au/scholarships/international-scholarships',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Newcastle own pages read on 2026-10-25: newcastle.edu.au/scholarships/international-scholarships describes the International Excellence Scholarship 2027 as a dollar value equivalent to 20% of the gross annual international tuition fee, applied pro-rata over each term, with no application and an outcome in the letter of offer for students commencing in Trimester 1 2027 and beyond; newcastle.edu.au/scholarships/UNI_053 gives the 20% annual value, the 500 places, the automatic assessment, the exclusion of programs under an international quota arrangement and the 2027 commencement window; the published terms and conditions PDF quantifies the same award at AUD 6 000 a year and AUD 750 per 10 units in the earlier version; the same international scholarships page lists the Excelencia Internacional Scholarship at 25% with fully funded on-campus accommodation for up to 12 weeks and up to 60 hours of English tuition restricted to South and Central America, and the AUD 1 500 Global Access Grant restricted to recipients of Newcastle own international scholarships. CORRECTIONS: the row claimed a Partial Tuition award worth USD 28 000, listed all three degree levels and gave a September-November deadline. The award is 20% of the annual international tuition fee with 500 places, it is coursework only, it needs no application and therefore has no deadline, and the 25% level belongs to a scholarship for Latin American applicants rather than to this one. amount_usd_value is 0 because the current version is defined as a percentage.'
WHERE id = 751;

-- 768 University of Wollongong
UPDATE scholarships SET
  title = 'University of Wollongong University Excellence Scholarship',
  description = 'Wollongong awards this automatically to every eligible high-achieving international undergraduate and there is no cap: the University Excellence Scholarship is a 30% tuition fee reduction for the minimum duration of an eligible course at an Australian campus. There is no application, no separate form and no deadline in the ordinary sense - eligible students are assessed on the qualification used for admission and the scholarship is issued with offers made from 12 June 2026 for students commencing in 2027 and beyond. A cumulative Weighted Average Mark of 50 is all that is needed to keep it from session to session, which is a maintenance bar rather than a selection bar; the selection bar is the published Group 3 entry score for the country and qualification. The exclusions are the real detail and they are all health, education and psychology degrees: nutrition and dietetics, nutrition science, exercise science, exercise science and rehabilitation, education across its variants, social work, psychological science and its honours year, arts in psychology, psychology honours, and any double degree containing one of them. It cannot be combined with another UOW tuition scholarship, sponsorship, bursary or discount for the same course, though stipend scholarships are allowed. The postgraduate equivalent, the Postgraduate Academic Excellence Scholarship, is also 30%.',
  requirements = 'Be an international student enrolling in an eligible UOW undergraduate course at an Australian campus, including honours degrees commenced the year after secondary school. Have outstanding results in one of the recognised pathways: Australian Year 12 or an approved international senior secondary qualification, a foundation studies program approved for direct entry, a diploma or academic pathway program with credit transfer from an institution with a formal agreement with UOW, or an approved academic program leading into a UOW bachelor degree. Meet the published Group 3 entry score for the country and qualification, since eligibility from secondary school results applies only where the qualification is accepted for Group 3 entry. Not be receiving any other UOW tuition scholarship, sponsorship, bursary or discount for the same course, although stipend scholarships are permitted. Maintain a cumulative WAM of 50 each session. Not enrol in one of the excluded health, education, social work or psychology degrees.',
  coverage_type = 'Partial Tuition', award_basis = 'variable', award_amount = NULL, award_currency = 'AUD', award_period = 'year',
  degree_levels = '["Bachelor''s"]', eligible_majors = '["All Majors"]', eligible_countries = '["All"]',
  funding_type = 'Merit-based tuition fee reduction',
  tuition_coverage = 'A 30% tuition fee reduction for the minimum duration of an eligible undergraduate course at an Australian campus. Unlimited number of awards. No living allowance.',
  english_requirements = 'The scholarship sets no separate English score; the UOW admission English requirement for the chosen degree applies.',
  required_documents = '["UOW admission application","Secondary school, foundation or diploma results used to apply the Group 3 entry score","English proficiency evidence","No separate scholarship application"]',
  deadline = 'No separate scholarship deadline; automatically assessed on application, and the scholarship is issued with offers from 12 June 2026 for 2027 commencements',
  deadline_date = NULL, deadline_type = 'automatic', application_status = 'open',
  website_url = 'https://www.uow.edu.au/study/scholarships/international/university-excellence-scholarships/',
  source_url = 'https://www.uow.edu.au/study/scholarships/international/university-excellence-scholarships/',
  application_url = 'https://www.uow.edu.au/study/scholarships/international/',
  verification_status = 'verified', source_reliability = 9, amount_usd_value = 0,
  last_updated_at = now(), last_verified_at = now(),
  notes = 'Rewritten from University of Wollongong own pages read on 2026-10-25: uow.edu.au/study/scholarships/international/university-excellence-scholarships gives the 30% tuition fee reduction for the minimum duration of an eligible course, the 2027 commencement, the Australian-campus requirement with the full exclusion list, full-time study load, international citizenship, no application required, an unlimited number of awards, the four eligible pathways, the requirement not to hold another scholarship, sponsorship, bursary or discount for the same course, the minimum cumulative WAM of 50, and the note that the scholarship is issued to eligible students with offers from 12 June 2026 for 2027 and beyond; uow.edu.au/study/international/representatives/international-entry-requirements explains that the 30% Undergraduate Excellence Scholarship is offered where the qualification is accepted for Group 3 entry and at the Group 3 eligibility score. CORRECTIONS: the row was titled University of Wollongong International Undergraduate Merit Scholarship, claimed a Partial Tuition award worth USD 25 000 and gave a November-December deadline. No award by that name exists; the real one is the University Excellence Scholarship at 30% of tuition, awarded automatically and without a cap, with a defined exclusion list. Also the old value implies a fixed dollar sum, which the university does not publish. amount_usd_value is 0 because UOW prices the award as a percentage.'
WHERE id = 768;

-- university_scholarships cards
UPDATE university_scholarships u SET scholarship_name = v.name, availability_status = 'Yes', funding_type = v.ftype, max_scholarship = v.mx, covers_tuition = true, covers_living_expenses = false, eligibility_notes = v.elig, official_url = v.url, source_url = v.url, verification_status = 'verified', last_verified_at = now()
FROM (VALUES
  (179, 'Adelaide Academic Excellence Scholarship (50%)', 'Merit-based', '50% tuition reduction; automatic 25%, 15% and 10% awards also exist', 'Adelaide University is the merged institution of the University of Adelaide and UniSA. The 50% award needs an application and an ATAR of 99 or a GPA of 6.7; the 25%, 15% and 10% awards are automatic. Applications opened 24 August 2026, rolling until places run out.', 'https://adelaide.edu.au/study/scholarships/int/adelaide-academic-excellence-scholarship-50/'),
  (199, 'John Curtin Global Excellence Scholarship', 'Merit-based', '40% off tuition for the duration; lower tiers at 20% and one-off credits of A$10 000 and A$15 000', 'Curtin grades its international ladder by academic record: 40% for the John Curtin Global Excellence Scholarship, 20% for the Global Merit Scholarship, plus one-off credits. No standalone closing date is published.', 'https://www.curtin.edu.au/study/scholarships/international-scholarships/'),
  (203, 'Deakin International Scholarship for Excellence (25%)', 'Merit-based', '25% of tuition for the duration; 20% merit tier; 100% or 50% Vice-Chancellor award by separate application', 'Most Deakin international awards are assessed automatically with the admission application; only the Vice-Chancellor International Scholarship needs a separate form.', 'https://www.deakin.edu.au/international-students/international-student-scholarships'),
  (227, 'Griffith Vice Chancellor International Scholarship', 'Merit-based', '50% of tuition for the whole degree', 'Entry requires a GPA of 6.0 on a 7.0 scale and a separate scholarship application with a personal statement. Closing dates: 28 November 2026 for Trimester 1 2027 and 10 April 2027 for Trimester 2 2027.','https://www.griffith.edu.au/international/scholarships-finance/scholarships/vice-chancellors-international-scholarship'),
  (213, 'La Trobe High Achiever Scholarship', 'Merit-based', '20% off tuition at WAM 60-74.9; 25% at WAM 75 or above', 'Automatic on application, no separate form. Full fee-paying non-sponsored international students only, eligible course list applies. Published closing date 31 December 2027; the A$2 000 Early Acceptance Grant can be added.','https://www.latrobe.edu.au/study/scholarships/other/la-trobe-high-achiever-scholarship'),
  (115, 'Macquarie University Vice-Chancellor International Scholarship', 'Merit-based', 'Up to AUD 10 000 one-off against tuition', 'Open year round. Requires a full offer plus a short scholarship application form, and a minimum ATAR equivalent of 85 or WAM equivalent of 65. Excludes applicants holding another Macquarie scholarship and Macquarie University College applicants.','https://www.mq.edu.au/study/admissions-and-entry/scholarships/international/vice-chancellor-s-international-scholarship/'),
  (297, 'QUT International Merit Scholarship', 'Merit-based', '25% of tuition per semester for the duration', 'Assessed automatically from the course application and stated in the offer. Faculty of Health courses receive 25% for the first two semesters only. Not available to students holding another QUT academic scholarship.','https://www.qut.edu.au/study/fees-and-scholarships/scholarships/international-merit-scholarship'),
  (106, 'RMIT Academic Merit Scholarship for Central Asia and Mongolia', 'Merit-based', '20% tuition reduction for the duration', 'Written for Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan, UZBEKISTAN and Mongolia. Requires offshore application, a GPA of 2.5 or 70% average or ATAR 75, a Semester 1 2027 offer and an Expression of Interest; first-come, first-served with a 14-day acceptance window.','https://www.rmit.edu.au/scholarships/international-scholarships/academic-merit-scholarship-central-asia-mongolia'),
  (281, 'University of Newcastle International Excellence Scholarship', 'Merit-based', '20% of the gross annual international tuition fee', 'Automatically assessed on application, 500 places for 2027 commencements, value stated in the letter of offer. Coursework only; excludes research, ELBP, exchange, Study Abroad, standalone graduate certificates and diplomas, and online or offshore delivery.','https://www.newcastle.edu.au/scholarships/UNI_053'),
  (133, 'University of Wollongong University Excellence Scholarship', 'Merit-based', '30% tuition reduction for the minimum duration of the course', 'Awarded automatically and without a cap to eligible international undergraduates at Australian campuses from 2027. Excludes nutrition, exercise science, education, social work and psychology degrees. Must maintain a cumulative WAM of 50.','https://www.uow.edu.au/study/scholarships/international/university-excellence-scholarships/')
) AS v(id, name, ftype, mx, elig, url)
WHERE u.id = v.id;
